try{if(window.jsQR){const d=cx.getImageData(0,0,cv.width,cv.height),q=jsQR(d.data,d.width,d.height);if(q)txt=q.data}else if("BarcodeDetector" in window){const r=await new BarcodeDetector({formats:["qr_code"]}).detect(cv);if(r[0])txt=r[0].rawValue}}catch(e){}
