function finishTicket(status){if(!D.token)return;D.hist.unshift({shop:D.at,code:D.code,token:D.token,start:D.joinedAt,end:Date.now(),status});if(D.hist.length>50)D.hist.length=50;save()}
function saveBtn(code){const on=D.saved.includes(code);return `<button class="ib" data-save="${code}" aria-pressed="${on}" aria-label="${on?"Remove from saved":"Save service"}" style="color:${on?"var(--blue)":"var(--mut)"}"><svg width="20" height="20" viewBox="0 0 24 24" fill="${on?"currentColor":"none"}" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${P.mark}"/></svg></button>`}
const selMatch=s=>!D.q||(s.n+" "+s.s+" "+s.t).toLowerCase().includes(D.q.toLowerCase());
const qBar=()=>D.q?`<div class="sp rise" style="margin-bottom:10px"><span class="mut">Results for “${esc(D.q)}”</span><button class="ln" data-clearq>Clear</button></div>`:"";
const selEmpty=()=>D.svc.some(selMatch)?"":`<div class="card rise" style="--i:1;text-align:center;padding:28px 14px"><h3>No services found</h3><p class="mut" style="margin:6px 0 16px">Nothing matches “${esc(D.q)}” yet.</p><button class="btn b1" data-clearq>Show all services</button></div>`;
function permInfo(){[["geolocation","perm-geo"],["camera","perm-cam"]].forEach(([n,id])=>{const el=document.getElementById(id);if(!el)return;if(!navigator.permissions||!navigator.permissions.query){el.textContent="Asked when used";return}navigator.permissions.query({name:n}).then(r=>{el.textContent=({granted:"Allowed",denied:"Blocked",prompt:"Asked when used"})[r.state]||"Asked when used"}).catch(()=>{el.textContent="Asked when used"})})}
